import{_ as t,o as e,c as l,a2 as s}from"./chunks/framework.D4up2k3b.js";const i="/filebox/docs/screenshots/03-collections.png",a="/filebox/docs/screenshots/03b-collections-watchlist.png",u=JSON.parse('{"title":"合集 Collections","description":"","frontmatter":{},"headers":[],"relativePath":"features/collections.md","filePath":"features/collections.md","lastUpdated":1791393728000}'),n={name:"features/collections.md"};function c(r,o,d,_,p,h){return e(),l("div",null,[...o[0]||(o[0]=[s('<h1 id="合集-collections" tabindex="-1">合集 Collections <a class="header-anchor" href="#合集-collections" aria-label="Permalink to &quot;合集 Collections&quot;">​</a></h1><p>合集是<strong>虚拟引用列表</strong>：把分散在不同目录（甚至不同 root）里的文件收进一个命名列表，不复制、不移动。列表存在 Agent 上。</p><p><img src="'+i+'" alt="Collections：watchlist"></p><p><img src="'+a+'" alt="从合集打开预览"></p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><ol><li>侧栏打开 <strong>Collections</strong>。</li><li>用下拉选择已有合集，或 <strong>+ New</strong> 创建。</li><li>在 <strong>Files</strong> / 预览里把文件加入合集（合集选择器）。</li><li>在合集视图中：并排查看、移除项、或跳回原始路径。</li><li><strong>Delete</strong> 只删除合集本身，不动真实文件。</li></ol><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>合集项指向 <code>(root, path)</code>；若源文件被移走，项会失效但不会改磁盘。</li><li>Agent 离线时 Hub 会把变更标为 pending，重连后再应用。</li><li>需要 Agent 具备 <code>collections</code> 能力（当前发布版默认具备）。</li></ul>',8)])])}const f=t(n,[["render",c]]);export{u as __pageData,f as default};
